using System.Collections;using System.Linq;using NUnit.Framework;using UnityEngine;using UnityEngine.TestTools;using UnityEngine.SceneManagement;using UnityEngine.UI;using CelestialMaker;
public class StartupTests {
 [SetUp]public void IsolateSave(){SaveStore.OverridePath=System.IO.Path.GetFullPath(System.IO.Path.Combine(Application.dataPath,"../../Logs/ObservatoryEvolution/PlayModeSaves/"+System.Guid.NewGuid().ToString("N")+".json"));}
 [TearDown]public void RestoreSavePath(){if(GameSession.Instance)Object.DestroyImmediate(GameSession.Instance.gameObject);GameSession.Instance=null;SaveStore.OverridePath=null;}
 [UnityTest]public IEnumerator BootstrapMenuGameProduction(){SceneManager.LoadScene("00_Bootstrap");yield return new WaitForSecondsRealtime(2);Assert.AreEqual("01_MainMenu",SceneManager.GetActiveScene().name);Assert.AreEqual(1,Object.FindObjectsByType<GameSession>(FindObjectsSortMode.None).Length);var session=GameSession.Instance;session.Saved=null;var start=Object.FindObjectsByType<Button>(FindObjectsSortMode.None).First(b=>b.name=="New Game");start.onClick.Invoke();yield return new WaitForSecondsRealtime(2);Assert.AreEqual("02_Game",SceneManager.GetActiveScene().name);double t=session.Sim.S.time;yield return new WaitForSecondsRealtime(1);Assert.Greater(session.Sim.S.time,t);Assert.AreEqual(1,Object.FindObjectsByType<AudioListener>(FindObjectsSortMode.None).Length);session.Sim.BeginOffline(3600);yield return new WaitUntil(()=>session.Sim.S.offlineRemaining==0);yield return new WaitForSecondsRealtime(.6f);Assert.IsTrue(Object.FindObjectsByType<Button>(FindObjectsSortMode.None).Any(b=>b.name=="Expand details"));var report=session.Sim.S.offlineReport;Assert.Greater(report.before[0].Value,BreakInfinity.BigDouble.Zero);Object.FindObjectsByType<Button>(FindObjectsSortMode.None).First(b=>b.name=="Expand details").onClick.Invoke();Assert.IsTrue(report.dismissed);session.Save();Assert.IsTrue(SaveStore.Load().offlineReport.dismissed);Object.Destroy(session.gameObject);}
}
